  "2-1-perpendicular-turn": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 330\" role=\"img\" aria-labelledby=\"t\" font-family=\"sans-serif\" font-size=\"13\">\n  <title id=\"t\">Perpendicular lines with gradients three quarters and minus four thirds, each shown by its rise and run triangle</title>\n  <line x1=\"10\" y1=\"285\" x2=\"342\" y2=\"36\" stroke=\"var(--t1-ink)\" stroke-width=\"2.5\"/>\n  <line x1=\"42\" y1=\"36\" x2=\"258\" y2=\"324\" stroke=\"var(--t5-ink)\" stroke-width=\"2.5\"/>\n  <path d=\"M150,180 L270,180 L270,90\" fill=\"none\" stroke=\"var(--t1-ink)\" stroke-width=\"1.5\" stroke-dasharray=\"5 3\"/>\n  <path d=\"M150,180 L150,300 L240,300\" fill=\"none\" stroke=\"var(--t5-ink)\" stroke-width=\"1.5\" stroke-dasharray=\"5 3\"/>\n  <path d=\"M159.6,172.8 L166.8,182.4 L157.2,189.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\"/>\n  <circle cx=\"150\" cy=\"180\" r=\"4\" fill=\"currentColor\"/>\n  <text x=\"210\" y=\"197\" text-anchor=\"middle\" fill=\"var(--t1-ink)\">4</text>\n  <text x=\"278\" y=\"140\" fill=\"var(--t1-ink)\">3</text>\n  <text x=\"138\" y=\"245\" text-anchor=\"end\" fill=\"var(--t5-ink)\">4</text>\n  <text x=\"195\" y=\"318\" text-anchor=\"middle\" fill=\"var(--t5-ink)\">3</text>\n  <text x=\"200\" y=\"70\" fill=\"var(--t1-ink)\">gradient 3/4</text>\n  <text x=\"74\" y=\"40\" fill=\"var(--t5-ink)\">gradient −4/3</text>\n</svg>",
  "2-1-road-slope": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 210\" role=\"img\" aria-labelledby=\"t\" font-family=\"sans-serif\" font-size=\"13\">\n  <title id=\"t\">A sloping road as the hypotenuse of a right-angled triangle, with the vertical rise and the horizontal distance as the other two sides</title>\n  <line x1=\"40\" y1=\"160\" x2=\"400\" y2=\"160\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/>\n  <line x1=\"400\" y1=\"160\" x2=\"400\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/>\n  <line x1=\"40\" y1=\"160\" x2=\"400\" y2=\"60\" stroke=\"var(--t2-ink)\" stroke-width=\"4\"/>\n  <path d=\"M388,160 L388,148 L400,148\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\"/>\n  <text x=\"220\" y=\"182\" text-anchor=\"middle\" fill=\"currentColor\">horizontal distance (the run)</text>\n  <text x=\"408\" y=\"104\" fill=\"currentColor\">vertical</text>\n  <text x=\"408\" y=\"120\" fill=\"currentColor\">rise</text>\n  <text x=\"200\" y=\"98\" text-anchor=\"middle\" fill=\"var(--t2-ink)\" transform=\"rotate(-15.5 200 98)\">length along the road</text>\n  <text x=\"220\" y=\"202\" text-anchor=\"middle\" fill=\"var(--muted)\">gradient = vertical rise ÷ horizontal distance</text>\n</svg>",
